  <title>Terms Consent</title>
  <style>
    :root {
      color-scheme: light;
      --bg: #f4f7fb;
      --surface: #ffffff;
      --surface-border: #d9e2f1;
      --text: #162033;
      --muted: #5a6882;
      --accent: #315efb;
      --accent-strong: #2448c7;
      --success-bg: #edf9f1;
      --success-text: #17653a;
      --error-bg: #fff1f2;
      --error-text: #b42318;
      --shadow: 0 24px 60px rgba(21, 33, 61, 0.12);
      --radius: 20px;
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
      background:
        radial-gradient(circle at top, #e8efff 0, transparent 38%),
        linear-gradient(180deg, #f8faff 0%, var(--bg) 100%);
      color: var(--text);
    }

    .skip-link {
      position: absolute;
      top: 1rem;
      left: 1rem;
      padding: 0.75rem 1rem;
      background: var(--text);
      color: #fff;
      border-radius: 0.75rem;
      transform: translateY(-140%);
      transition: transform 0.2s ease;
      z-index: 10;
    }

    .skip-link:focus {
      transform: translateY(0);
    }

    main {
      min-height: 100vh;
      display: grid;
      place-items: center;
      padding: 1.5rem;
    }

    .card {
      width: min(100%, 28rem);
      padding: 2rem;
      background: rgba(255, 255, 255, 0.96);
      border: 1px solid var(--surface-border);
      border-radius: var(--radius);
      box-shadow: var(--shadow);
      backdrop-filter: blur(12px);
    }

    .eyebrow {
      margin: 0 0 0.75rem;
      font-size: 0.875rem;
      font-weight: 700;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      color: var(--accent);
    }

    h1 {
      margin: 0;
      font-size: clamp(1.75rem, 4vw, 2.25rem);
      line-height: 1.1;
    }

    .intro {
      margin: 0.9rem 0 1.5rem;
      color: var(--muted);
      line-height: 1.55;
    }

    form {
      display: grid;
      gap: 1rem;
    }

    .form-field {
      display: grid;
      gap: 0.6rem;
      padding: 1rem;
      border: 1px solid var(--surface-border);
      border-radius: 1rem;
      background: #f9fbff;
    }

    .checkbox-row {
      display: flex;
      align-items: start;
      gap: 0.8rem;
    }

    input[type="checkbox"] {
      width: 1.15rem;
      height: 1.15rem;
      margin-top: 0.15rem;
      accent-color: var(--accent);
      flex: 0 0 auto;
    }

    label {
      font-weight: 600;
      line-height: 1.45;
    }

    .helper-text {
      margin: 0;
      font-size: 0.95rem;
      color: var(--muted);
      line-height: 1.5;
    }

    .error-text,
    .status {
      min-height: 1.25rem;
      margin: 0;
      font-size: 0.95rem;
      line-height: 1.4;
    }

    .error-text {
      color: var(--error-text);
    }

    .status {
      padding: 0.9rem 1rem;
      border-radius: 0.9rem;
      background: transparent;
      color: transparent;
    }

    .status[data-state="success"] {
      background: var(--success-bg);
      color: var(--success-text);
    }

    button {
      border: 0;
      border-radius: 999px;
      padding: 0.95rem 1.25rem;
      font: inherit;
      font-weight: 700;
      background: linear-gradient(135deg, var(--accent), #5d83ff);
      color: #fff;
      cursor: pointer;
      transition: transform 0.15s ease, box-shadow 0.15s ease, background 0.15s ease;
      box-shadow: 0 16px 30px rgba(49, 94, 251, 0.22);
    }

    button:hover {
      transform: translateY(-1px);
      background: linear-gradient(135deg, var(--accent-strong), #4e73eb);
    }

    button:focus-visible,
    input[type="checkbox"]:focus-visible {
      outline: 3px solid #111827;
      outline-offset: 3px;
    }

    @media (max-width: 480px) {
      .card {
        padding: 1.4rem;
      }
    }

    @media (forced-colors: active) {
      body {
        background: Canvas;
        color: CanvasText;
      }

      .card,
      .form-field,
      .status[data-state="success"] {
        background: Canvas;
        border-color: ButtonBorder;
        box-shadow: none;
      }

      .eyebrow,
      .helper-text,
      .intro,
      .status[data-state="success"],
      .error-text {
        color: CanvasText;
      }

      button {
        background: ButtonFace;
        color: ButtonText;
        border: 1px solid ButtonBorder;
        box-shadow: none;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>
  <main id="main-content">
    <section class="card" aria-labelledby="page-title">
      <p class="eyebrow">Product access</p>
      <h1 id="page-title">Confirm your consent</h1>
      <p class="intro">Review this quick step before continuing to your account setup.</p>

      <form id="consent-form" novalidate>
        <div class="form-field">
          <div class="checkbox-row">
            <input
              id="terms-consent"
              name="terms-consent"
              type="checkbox"
              required
              aria-describedby="terms-helper terms-error"
            >
            <label for="terms-consent">I agree to the Terms of Use</label>
          </div>
          <p id="terms-helper" class="helper-text">Required to continue with your submission.</p>
          <p id="terms-error" class="error-text" aria-live="polite"></p>
        </div>

        <button type="submit">Submit</button>
        <p id="form-status" class="status" aria-live="polite"></p>
      </form>
    </section>
  </main>

  <script>
    const form = document.getElementById('consent-form');
    const checkbox = document.getElementById('terms-consent');
    const errorText = document.getElementById('terms-error');
    const status = document.getElementById('form-status');

    const showError = () => {
      errorText.textContent = 'Please agree to the Terms of Use before submitting.';
      checkbox.setAttribute('aria-invalid', 'true');
      status.textContent = '';
      status.dataset.state = '';
    };

    const clearError = () => {
      errorText.textContent = '';
      checkbox.removeAttribute('aria-invalid');
    };

    checkbox.addEventListener('change', () => {
      if (checkbox.checked) {
        clearError();
      }
    });

    form.addEventListener('submit', (event) => {
      if (!checkbox.checked) {
        event.preventDefault();
        showError();
        checkbox.focus();
        return;
      }

      event.preventDefault();
      clearError();
      status.textContent = 'Consent recorded. You can move to the next step.';
      status.dataset.state = 'success';
    });
  </script>
</body>
</html>
